var ROW_MAJOR = require( './fixtures/row_major.json' );
var COL_MAJOR_K_LT_N = require( './fixtures/column_major_k_lt_n.json' );
var ROW_MAJOR_K_LT_N = require( './fixtures/row_major_k_lt_n.json' );

